create function pg_temp.fail_transfer_completion() returns trigger language plpgsql set search_path='' as $$
begin
  if new.event_type='organization_transfer.completed' and exists(select 1 from pg_temp.request_ids r where r.label='18' and r.id=new.target_id) then
    raise exception using errcode='P0001',message='Intentional completion audit failure';
  end if;
  return new;
end;
$$;
create trigger transfer_test_failure before insert on public.audit_logs for each row execute function pg_temp.fail_transfer_completion();
set local role authenticated;
set local request.jwt.claims='{"sub":"f5100000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}';
select extensions.throws_ok('select public.review_organization_transfer((select id from request_ids where label=''18''),1,''approve'',''super_admin'')','P0001',null,'Late audit failure rolls back the full membership switch');
reset role;
drop trigger transfer_test_failure on public.audit_logs;
select extensions.ok((select status='active' from public.organization_members where user_id='f5100000-0000-4000-8000-000000000018' and organization_id='f5200000-0000-4000-8000-000000000001'),'Late failure preserves source membership');
select extensions.ok((select count(*)=0 from public.organization_members where user_id='f5100000-0000-4000-8000-000000000018' and organization_id='f5200000-0000-4000-8000-000000000002'),'Late failure leaves no target membership');
select extensions.ok((select status='pending' and revision=1 from public.organization_change_requests where id=(select id from request_ids where label='18')),'Late failure leaves request pending at original revision');
select extensions.ok((select count(*)=0 from public.audit_logs where target_id=(select id from request_ids where label='18') and event_type='organization_transfer.completed'),'Late failure leaves no partial completion audit');

select * from extensions.finish(); rollback;
